def zh(name, osm_zh=None):
    if osm_zh: return osm_zh
    if not name: return None
    if name in ZH: return ZH[name]
    n2 = name.replace('–', '-')
    if n2 in ZH: return ZH[n2]
    for suf, z in ((' County', '县'),):
        if name.endswith(suf) and name[:-len(suf)] in ZH: return ZH[name[:-len(suf)]] + z
    # numbered streets and avenues: "West 42nd Street" -> 西42街, "East 86th Street" -> 东86街, "42nd Street" -> 42街
    import re
    m = re.match(r'^(West |East |North |South )?(\d+)(st|nd|rd|th) (Street|Avenue|Road|Place|Drive)$', name)
    if m:
        pre = {'West ':'西', 'East ':'东', 'North ':'北', 'South ':'南'}.get(m.group(1) or '', '')
        return pre + m.group(2) + {'Street':'街', 'Avenue':'大道', 'Road':'路', 'Place':'坊', 'Drive':'路'}[m.group(4)]
    return None
